import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Library: none — native interpolate/spring with @remotion/paths for draw-on

const { fontFamily } = loadFont();



export type PerformanceChartProps = Record<string, any>;

const PerformanceChart: React.FC<PerformanceChartProps> = ({
  backgroundColor = "#f5f5f7",
  transparentBackground = false,
  durationInSeconds = 8,
  titleLine1 = "2x faster.",
  titleLine2 = "Half the power.",
  primaryColor = "#0066cc",
  textColor = "#1d1d1f",
  prevGenLabel = "Previous generation",
  newGenLabel = "M4",
  xAxisLabel = "Power",
  yAxisLabel = "Performance",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Parser safety for transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Chart Geometry Coordinates
  const x0 = width * 0.12;
  const y0 = height * 0.85;

  // Previous Generation Curve (Flatter)
  const p1x_prev = width * 0.4;
  const p1y_prev = height * 0.85;
  const p2x_prev = width * 0.7;
  const p2y_prev = height * 0.75;
  const p3x_prev = width * 0.85;
  const p3y_prev = height * 0.65;
  const prevGenPath = `M ${x0} ${y0} C ${p1x_prev} ${p1y_prev}, ${p2x_prev} ${p2y_prev}, ${p3x_prev} ${p3y_prev}`;

  // New Generation Curve (Steeper)
  const p1x_new = width * 0.5;
  const p1y_new = height * 0.85;
  const p2x_new = width * 0.7;
  const p2y_new = height * 0.5;
  const p3x_new = width * 0.85;
  const p3y_new = height * 0.35;
  const newGenPath = `M ${x0} ${y0} C ${p1x_new} ${p1y_new}, ${p2x_new} ${p2y_new}, ${p3x_new} ${p3y_new}`;

  // Axes (L-shape)
  const axisPath = `M ${x0} ${height * 0.45} L ${x0} ${y0} L ${width * 0.85} ${y0}`;

  // Animations - Headline
  const headlineOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" });
  const headlineY = interpolate(frame, [0, 20], [20 * s, 0], { 
    extrapolateRight: "clamp", 
    easing: Easing.out(Easing.cubic) 
  });
  
  // Animations - Axes
  const axisOpacity = interpolate(frame, [15, 35], [0, 1], { extrapolateRight: "clamp" });
  
  // Animations - Previous Gen
  const prevGenProgress = interpolate(frame, [35, 85], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp", 
    easing: Easing.inOut(Easing.ease) 
  });
  const prevEvolution = evolvePath(prevGenProgress, prevGenPath);
  const prevGenOpacity = interpolate(frame, [85, 100], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  
  // Animations - New Gen
  const newGenProgress = interpolate(frame, [90, 150], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp", 
    easing: Easing.inOut(Easing.ease) 
  });
  const newEvolution = evolvePath(newGenProgress, newGenPath);
  
  // Animations - Endpoint Dot & Final Label
  const dotScale = spring({
    frame: frame - 150,
    fps,
    config: { damping: 12, stiffness: 100 }
  });
  const m4LabelOpacity = interpolate(frame, [150, 165], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily }}>
      
      {/* SVG Layer for Axes and Curves */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0, overflow: "visible" }}>
        
        {/* Minimal Axes */}
        <path
          d={axisPath}
          stroke={textColor}
          strokeWidth={2 * s}
          fill="none"
          style={{ 
            opacity: axisOpacity, 
            transition: "none" 
          }}
        />
        
        {/* Previous Generation Path */}
        <path
          d={prevGenPath}
          stroke="#b0b0b5"
          strokeWidth={4 * s}
          fill="none"
          strokeDasharray={prevEvolution.strokeDasharray}
          strokeDashoffset={prevEvolution.strokeDashoffset}
          style={{ 
            transition: "none", 
            opacity: frame >= 35 ? 1 : 0 
          }}
        />
        
        {/* New Generation Path */}
        <path
          d={newGenPath}
          stroke={primaryColor}
          strokeWidth={8 * s}
          fill="none"
          strokeLinecap="round"
          strokeDasharray={newEvolution.strokeDasharray}
          strokeDashoffset={newEvolution.strokeDashoffset}
          style={{ 
            transition: "none", 
            opacity: frame >= 90 ? 1 : 0 
          }}
        />
        
        {/* Endpoint Dot */}
        <circle 
          cx={p3x_new} 
          cy={p3y_new} 
          r={12 * s} 
          fill={primaryColor} 
          style={{ 
            transform: `scale(${dotScale})`, 
            transformOrigin: `${p3x_new}px ${p3y_new}px`,
            opacity: frame >= 150 ? 1 : 0,
            transition: "none"
          }} 
        />
      </svg>
      
      {/* HTML Layer for Typography */}
      
      {/* Keynote Headline */}
      <div style={{
        position: "absolute",
        left: width * 0.08,
        top: height * 0.12,
        opacity: headlineOpacity,
        transform: `translateY(${headlineY}px)`,
        display: "flex",
        flexDirection: "column",
        gap: 4 * s,
        transition: "none"
      }}>
        <div style={{ fontSize: 96 * s, fontWeight: 700, color: primaryColor, letterSpacing: "-0.03em", lineHeight: 1.1 }}>
          {titleLine1}
        </div>
        <div style={{ fontSize: 96 * s, fontWeight: 700, color: textColor, letterSpacing: "-0.03em", lineHeight: 1.1 }}>
          {titleLine2}
        </div>
      </div>
      
      {/* Previous Gen Reference Label */}
      <div style={{
        position: "absolute",
        left: p3x_prev + 20 * s,
        top: p3y_prev - 16 * s,
        width: 140 * s,
        color: "#86868b",
        fontSize: 20 * s,
        lineHeight: 1.2,
        opacity: prevGenOpacity,
        fontWeight: 500,
        transition: "none"
      }}>
        {prevGenLabel}
      </div>

      {/* New Gen Highlight Label */}
      <div style={{
        position: "absolute",
        left: p3x_new + 32 * s,
        top: p3y_new - 28 * s,
        color: primaryColor,
        fontSize: 48 * s,
        fontWeight: 700,
        opacity: m4LabelOpacity,
        letterSpacing: "-0.02em",
        transition: "none"
      }}>
        {newGenLabel}
      </div>
      
      {/* Y Axis Label (Rotated) */}
      <div style={{
        position: "absolute",
        left: x0 - 90 * s,
        top: 0,
        bottom: 0,
        width: 40 * s,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        opacity: axisOpacity,
        transition: "none"
      }}>
        <div style={{
          transform: "rotate(-90deg)",
          whiteSpace: "nowrap",
          color: textColor,
          fontSize: 24 * s,
          fontWeight: 500,
        }}>
          {yAxisLabel}
        </div>
      </div>
      
      {/* X Axis Label */}
      <div style={{
        position: "absolute",
        left: x0,
        width: width * 0.73,
        top: y0 + 24 * s,
        display: "flex",
        justifyContent: "center",
        color: textColor,
        fontSize: 24 * s,
        fontWeight: 500,
        opacity: axisOpacity,
        transition: "none"
      }}>
        {xAxisLabel}
      </div>
      
    </AbsoluteFill>
  );
};

export default PerformanceChart;